{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In humans, the absolute oral bioavailability of HP-β-CD was estimated to be less than 1% following oral administration as a solution, which is far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "In humans, acarbose showed negligible absolute oral bioavailability of <2% based on plasma concentrations and urinary recovery compared with intravenous administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "In humans, the absolute oral bioavailability of unchanged glycyrrhizin from oral tablets was approximately 0.25% compared with injections, well below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved evidence molecules consistently show low oral bioavailability in humans, with numeric absolute or systemic values well below 20% (e.g., <1%, ~0.25%, <2%, 4.1%, 0.5–1.7%). The prediction is therefore low.",
  "evidence_gaps": [
    "Some records report qualitative 'low' or 'poor' bioavailability without numeric values, but multiple numeric absolute records provide threshold-relevant support.",
    "A few records involve specific formulations or co-administered products that may affect absorption, but the direction of evidence remains consistently low."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

